/// <summary>
/// MPJ_17526 - Rajesh - 10/06/2021
/// The <c>PrintMgmtDelegatesHandler</c> class extension
/// </summary>
[ExtensionOf(classStr(PrintMgmtDelegatesHandler))]
final class METPrintMgmtDelegatesHandler_Extension
{

}

Method.Source:
    /// <summary>
    /// Determines the party type for a journal records and the current document type.
    /// </summary>
    /// <param name="_docType">
    /// Type of the document.
    /// </param>
    /// <param name="_jour">
    /// A journal record.
    /// </param>
    /// <returns>
    /// A member of <c>PrintMgmtPrintDestinationPartyType</c>.
    /// </returns>
    /// <exception cref="Exception::Error">
    /// An invalid combination of journal record and document type was found.
    /// </exception>
    protected static PrintMgmtPrintDestinationPartyType getPartyType(PrintMgmtDocumentType _docType, Common _jour)
    {
        PrintMgmtPrintDestinationPartyType  destinationPartyType = next getPartyType(_docType, _jour);

        if(_docType == PrintMgmtDocumentType::METCustActivityStatement)
        {
            destinationPartyType = PrintMgmtPrintDestinationPartyType::Customer;
        }
        //MPJ_15231_Customer Statement DCP 29/03/2022
        else if(_docType == PrintMgmtDocumentType::METCustActivityStatementMulti)
        {
            destinationPartyType = PrintMgmtPrintDestinationPartyType::Customer;
        }

        return destinationPartyType;
    }

    public static void add(
        PrintMgmtDocumentType _type,
        PrintMgmtReportFormatName _name,
        PrintMgmtReportFormatDescription _description,
        PrintMgmtReportFormatCountryRegionId _countryRegionId,
        PrintMgmtReportFormatSystem _system, 
        PrintMgmtSSRS _ssrs = PrintMgmtSSRS::SSRS)
    {
        PrintMgmtReportFormat printMgmtReportFormat;
        boolean isDuplicateFound;
        boolean isSystemFormatWithDifferentDescriptionFound;

        #PrintMgmtSetup

        if(_type == PrintMgmtDocumentType::METCustActivityStatement)
        {
            isDuplicateFound = (select RecId from printMgmtReportFormat
                where printMgmtReportFormat.DocumentType == _type
                    && printMgmtReportFormat.Description == _description
                    && printMgmtReportFormat.CountryRegionId == _countryRegionId).RecId != 0;

            if (isDuplicateFound)
            {
                {
                    // We must ensure that the system report always matches the country context
                    // of the company. If the the country context has been chagned multiple times
                    // such that the report format already exists, we must change it back to system.
                    update_recordSet printMgmtReportFormat
                        setting System = true
                        where printMgmtReportFormat.DocumentType == _type
                            && printMgmtReportFormat.Description == _description
                            && printMgmtReportFormat.CountryRegionId == _countryRegionId;
                }
           
            }
            else
            {
                // Add the new format
                printMgmtReportFormat.clear();
                printMgmtReportFormat.DocumentType = _type;
                printMgmtReportFormat.Name = _name;
                printMgmtReportFormat.Description = _description;
                printMgmtReportFormat.CountryRegionId = _countryRegionId;
                printMgmtReportFormat.System = _system;
                printMgmtReportFormat.ssrs = _ssrs;
                printMgmtReportFormat.insert();
            }
        }
    }
